--
-- Table structure for table `land_records`
--

DROP TABLE IF EXISTS `land_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `land_records` (
  `record_id` bigint NOT NULL AUTO_INCREMENT,
  `survey_no` varchar(20) NOT NULL,
  `sheet_no` int DEFAULT NULL,
  `khate_no` int DEFAULT NULL,
  `bhoomapan_kramank` int DEFAULT NULL,
  `village` varchar(100) NOT NULL,
  `taluka` varchar(50) NOT NULL,
  `district` varchar(50) NOT NULL,
  `owner_name` varchar(150) DEFAULT NULL,
  `father_name` varchar(150) DEFAULT NULL,
  `owner_address` varchar(300) DEFAULT NULL,
  `mobile_no` varchar(15) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `land_type` varchar(50) NOT NULL,
  `ready_reckoner_rate_rs_sqft` decimal(15,2) DEFAULT NULL,
  `latitude` decimal(10,6) DEFAULT NULL,
  `longitude` decimal(10,6) DEFAULT NULL,
  `land_area_sqft` decimal(15,2) NOT NULL,
  `land_category` varchar(20) DEFAULT NULL,
  `soil_type` varchar(50) DEFAULT NULL,
  `irrigation_type` varchar(50) DEFAULT NULL,
  `road_connectivity` varchar(20) DEFAULT NULL,
  `distance_highway_km` decimal(6,2) DEFAULT NULL,
  `distance_city_km` decimal(6,2) DEFAULT NULL,
  `distance_school_km` decimal(6,2) DEFAULT NULL,
  `distance_hospital` decimal(6,2) DEFAULT NULL,
  `distance_market` decimal(6,2) DEFAULT NULL,
  `historical_price` decimal(15,2) DEFAULT NULL,
  `government_rate` decimal(15,2) DEFAULT NULL,
  `sale_price` decimal(15,2) DEFAULT NULL,
  `current_market_price` decimal(15,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

