DROP TABLE IF EXISTS `satbara_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `satbara_records` (
  `satbara_id` bigint NOT NULL AUTO_INCREMENT,
  `record_id` bigint NOT NULL,
  `survey_no` varchar(255) DEFAULT NULL,
  `village` varchar(255) DEFAULT NULL,
  `taluka` varchar(255) DEFAULT NULL,
  `district` varchar(255) DEFAULT NULL,
  `sheet_no` int DEFAULT NULL,
  `area_hectare` decimal(38,2) DEFAULT NULL,
  `land_type` varchar(255) DEFAULT NULL,
  `owner_name` varchar(255) DEFAULT NULL,
  `owner_address` varchar(255) DEFAULT NULL,
  `kshetra` varchar(255) DEFAULT NULL,
  `acre_aakaar` int DEFAULT NULL,
  `bhogatdar_varga` varchar(255) DEFAULT NULL,
  `pik_paddhati` varchar(255) DEFAULT NULL,
  `potkharcha` decimal(38,2) DEFAULT NULL,
  `fress` decimal(38,2) DEFAULT NULL,
  `itar` decimal(38,2) DEFAULT NULL,
  `ekun_aakarani` decimal(38,2) DEFAULT NULL,
  `kharip_crop` varchar(255) DEFAULT NULL,
  `kharip_area` decimal(38,2) DEFAULT NULL,
  `kharip_aakarani` decimal(38,2) DEFAULT NULL,
  `rabi_crop` varchar(255) DEFAULT NULL,
  `rabi_area` decimal(38,2) DEFAULT NULL,
  `rabi_aakarani` decimal(38,2) DEFAULT NULL,
  `itar_adhikar` varchar(255) DEFAULT NULL,
  `document_id` varchar(255) DEFAULT NULL,
  `generated_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `generated_by` varchar(255) DEFAULT NULL,
  `talathi_name` varchar(255) DEFAULT NULL,
  `verification_status` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`satbara_id`),
  KEY `record_id` (`record_id`),
  CONSTRAINT `satbara_records_ibfk_1` FOREIGN KEY (`record_id`) REFERENCES `land_records` (`record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

